39	const VERT = /* glsl */ `
40	uniform mat4 uProjVP;
41	varying vec4 vProj;
42	varying vec3 vW;
43	varying vec3 vN;
44	varying vec3 vL;
45	void main() {
46	  vec4 wp = modelMatrix * vec4(position, 1.0);
47	  vProj = uProjVP * wp;
48	  vW = wp.xyz;
49	  vL = position;
50	  vN = normalize(mat3(modelMatrix) * normal);
51	  gl_Position = projectionMatrix * viewMatrix * wp;
52	}`;
53	
54	const FRAG = /* glsl */ `
55	uniform sampler2D uPlate;
56	uniform sampler2D uDepth;
57	uniform float uUseDepth;
58	uniform vec2 uNearFar;
59	uniform sampler2D uPatch;
60	uniform float uPatchK;
61	uniform vec3 uProjPos;
62	uniform vec4 uPjPost;
63	uniform vec2 uPjRes;
64	uniform float uMode;          // 0 room wall / mouth ring: artwork patch; 1 tunnel wall: painted ring tile; 2 water: painted river tile
65	uniform sampler2D uTile;
66	uniform vec4 uTileA;          // mode 1: cx, cy, mouth z, ring period | mode 2: lateral half-width, along start, along length, -
67	uniform float uLipS;
68	uniform sampler2D uFill;      // plate04_fillmask: where the plate is a provisional fill (HUD, title, Benny, coins)
69	uniform float uMoved;         // 0 in the approved view, 1 once the camera has moved away from it
70	uniform vec2 uKeep;           // stretch-guard hand-over (milestone 2: 2.5..6; milestone 3 tunnel wall: earlier, sharper rings)
71	uniform float uR3;            // milestone 3 river (&river04=0 = milestone 2): swirl tile from the painted water around Benny
72	uniform sampler2D uRiv3;      //   tile_river3.png (pink ribbons, cyan streams, foam banks)
73	uniform vec4 uRiv3A;          //   lateral half-width, along start, along length, mouth distance down the slide
74	varying vec4 vProj;
75	varying vec3 vW;
76	varying vec3 vN;
77	varying vec3 vL;
78	${PROJ05_INVERSE}
79	// triplanar, mirrored-repeat sampling (slide-local coordinates) of the patch cut from the approved artwork
80	vec3 patchColor() {
81	  vec3 n = abs(normalize(vN)); n /= max(n.x + n.y + n.z, 1e-4);
82	  vec3 p = vL * uPatchK;
83	  return texture2D(uPatch, p.zy).rgb * n.x + texture2D(uPatch, p.xz).rgb * n.y + texture2D(uPatch, p.xy).rgb * n.z;
84	}
85	float linZ(float d) { float n = uNearFar.x, f = uNearFar.y; float z = d * 2.0 - 1.0; return 2.0 * n * f / (f + n - z * (f - n)); }
86	// milestone 2: world-anchored design tiles cut from the approved artwork for the views the picture never resolved
87	vec3 tileColor(vec3 pc) {
88	  if (uMode > 0.5 && uMode < 1.5) {
89	    vec2 rel = vL.xy - uTileA.xy;
90	    float psi = atan(-rel.x, rel.y);                       // 0 = tunnel top, seam at the bottom (under the water)
91	    float ax = uTileA.z - vL.z;                            // distance down the tunnel from the mouth
92	    vec2 uv = vec2(psi / 6.2831853 + 0.5, (ax - 7.1) / uTileA.w + uLipS);
93	    return textureGrad(uTile, uv, vec2(dFdx(uv.x), dFdx(uv.y)) * vec2(step(abs(dFdx(uv.x)), 0.5), 1.0),
94	                       vec2(dFdy(uv.x), dFdy(uv.y)) * vec2(step(abs(dFdy(uv.x)), 0.5), 1.0)).rgb;
95	  }
96	  if (uMode > 1.5 && uR3 > 0.5) {
97	    float along = -vL.z;
98	    // inside the tunnel the visible water is narrower: draw the painted banks a little closer to the walls
99	    float k = mix(1.0, 1.3, smoothstep(uRiv3A.w - 1.0, uRiv3A.w + 3.0, along));
100	    vec2 uv3 = vec2(vL.x * k / (2.0 * uRiv3A.x) + 0.5, (along - uRiv3A.y) / uRiv3A.z);
101	    vec3 sw = texture2D(uRiv3, uv3).rgb;
102	    vec4 ch = texture2D(uTile, vec2(vL.x / (2.0 * uTileA.x) + 0.5, (along - uTileA.y) / uTileA.z));  // tile_chev3: arrow + alpha
103	    vec3 col = mix(sw, ch.rgb, ch.a);
104	    float inRiver = 1.0 - smoothstep(0.9 * uRiv3A.x, uRiv3A.x, abs(vL.x * k));
105	    return mix(pc, col, inRiver);
106	  }
107	  if (uMode > 1.5) {
108	    float along = -vL.z;                                    // down the slide from Benny's water point
109	    vec2 uv = vec2(vL.x / (2.0 * uTileA.x) + 0.5, (along - uTileA.y) / uTileA.z);
110	    float inRiver = 1.0 - smoothstep(0.9 * uTileA.x, uTileA.x, abs(vL.x));
111	    return mix(pc, texture2D(uTile, uv).rgb, inRiver);
112	  }
113	  return pc;
114	}
115	void main() {
116	  vec3 pc = tileColor(patchColor());
117	  vec3 t = pc;
118	  vec3 nn = normalize(vN);
119	  float cp = abs(dot(nn, normalize(uProjPos - vW))), cc = abs(dot(nn, normalize(cameraPosition - vW)));
120	  // stretch + magnification guard: the projection is used where the current view sees the surface no more face-on and
121	  // no more magnified than the approved view did (incidence-cosine ratio x distance ratio = 1 in the approved view)
122	  float mag = (cc / max(cp, 1e-3)) * (distance(uProjPos, vW) / max(distance(cameraPosition, vW), 1e-3));
123	  float keep = 1.0 - smoothstep(uKeep.x, uKeep.y, mag);
124	  if (vProj.w > 0.0) {
125	    vec3 ndc = vProj.xyz / vProj.w;
126	    vec2 uv = ndc.xy * 0.5 + 0.5;
127	    if (uv.x >= 0.0 && uv.x <= 1.0 && uv.y >= 0.0 && uv.y <= 1.0) {
128	      float vis = 1.0;
129	      if (uUseDepth > 0.5) {
130	        float zs = linZ(texture2D(uDepth, uv).r), zf = linZ(ndc.z * 0.5 + 0.5);
131	        vis = 1.0 - smoothstep(0.015 * zs, 0.04 * zs + 0.05, zf - zs);
132	      }
133	      // provisional fill (no painted pixels there) gives way to the painted tiles once the camera moves
134	      float fill = uMode > 1.5 ? texture2D(uFill, uv).r * uMoved : 0.0;   // water only (the coin fills on the bank stay)
135	      t = mix(pc, texture2D(uPlate, uv).rgb, vis * keep * (1.0 - fill));
136	    }
137	  }
138	  gl_FragColor = vec4(pjInverse(t), 1.0);
139	}`;
